import React, { useState, useEffect } from 'react';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Dashboard from './pages/Dashboard';
import { readAuth, saveAuth, clearAuth } from './utils/auth';

function App(){
  const [auth, setAuth] = useState(readAuth());
  const [view, setView] = useState(auth ? 'dashboard' : 'login');

  useEffect(()=> { saveAuth(auth); }, [auth]);

  const logout = () => { clearAuth(); setAuth(null); setView('login'); };

  return (
    <div style={{ padding: 24, maxWidth: 1000, margin: '0 auto' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2>Learning Task Manager</h2>
        {auth && <div>
          <span style={{ marginRight: 12 }}>{auth.email} ({auth.role})</span>
          <button onClick={logout}>Logout</button>
        </div>}
      </header>

      <main style={{ marginTop: 20 }}>
        {view === 'login' && <Login onLogin={(u)=>{ setAuth(u); setView('dashboard'); }} onSwitch={()=>setView('signup')} />}
        {view === 'signup' && <Signup onSignup={(u)=>{ setAuth(u); setView('dashboard'); }} onSwitch={()=>setView('login')} />}
        {view === 'dashboard' && auth && <Dashboard auth={auth} />}
      </main>
    </div>
  );
}

export default App;
